import{_ as a,o,c as n,ae as r}from"./chunks/framework.EHGTsUvI.js";const y=JSON.parse('{"title":"Creating a Company","description":"","frontmatter":{"title":"Creating a Company"},"headers":[],"relativePath":"Main/Main/Company/creating-company.md","filePath":"Main/Main/Company/creating-company.md"}'),t={name:"Main/Main/Company/creating-company.md"};function i(s,e,p,m,l,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="creating-a-company" tabindex="-1">Creating a Company <a class="header-anchor" href="#creating-a-company" aria-label="Permalink to &quot;Creating a Company&quot;">​</a></h1><p>Companies allow players to work together and complete Company Orders as a team.</p><p>Players can create their own Company and become its <strong>Owner</strong>, giving them control over the Company&#39;s members, roles, and permissions.</p><h2 id="creation-costs" tabindex="-1">Creation Costs <a class="header-anchor" href="#creation-costs" aria-label="Permalink to &quot;Creation Costs&quot;">​</a></h2><p>Creating a Company requires Coins.</p><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Company Creation Cost</td><td><strong>[Confirm in-game] Coins</strong></td></tr><tr><td>Additional Cost</td><td>None currently confirmed</td></tr></tbody></table><blockquote><p><strong>Note:</strong> The Company creation price may be changed by Dunn Games in future updates or Seasons.</p></blockquote><h2 id="creating-a-company-1" tabindex="-1">Creating a Company <a class="header-anchor" href="#creating-a-company-1" aria-label="Permalink to &quot;Creating a Company&quot;">​</a></h2><p>To create a Company:</p><ol><li>Open the <strong>Company</strong> menu.</li><li>Select <strong>Create Company</strong>.</li><li>Enter a name for your Company.</li><li>Confirm the Company creation requirements.</li><li>Pay the required creation cost.</li><li>Confirm the creation.</li></ol><p>Once created, you become the <strong>Company Owner</strong>.</p><h2 id="company-name" tabindex="-1">Company Name <a class="header-anchor" href="#company-name" aria-label="Permalink to &quot;Company Name&quot;">​</a></h2><p>The Company Owner chooses the name of the Company when it is created.</p><p>The name is used to identify the Company to other players and its members.</p><blockquote><p><strong>Tip:</strong> Choose a name that is easy for your members to recognise, especially if you plan on recruiting multiple players.</p></blockquote><h2 id="company-owner" tabindex="-1">Company Owner <a class="header-anchor" href="#company-owner" aria-label="Permalink to &quot;Company Owner&quot;">​</a></h2><p>The player who creates the Company becomes its <strong>Owner</strong>.</p><p>The Owner has the highest level of control over the Company and can manage Company members and permissions.</p><p>The Owner can also assign roles to other members where supported.</p><p>For more information about Company roles and permissions, see <a href="./permissions.html">Roles &amp; Permissions</a>.</p><h2 id="joining-a-company" tabindex="-1">Joining a Company <a class="header-anchor" href="#joining-a-company" aria-label="Permalink to &quot;Joining a Company&quot;">​</a></h2><p>Players who do not want to create their own Company can join an existing Company.</p><p>A Company Owner or member with the appropriate permission can invite other players to join.</p><p>Once accepted, the player becomes a Company member and can participate in Company activities according to their assigned permissions.</p><h2 id="company-progression" tabindex="-1">Company Progression <a class="header-anchor" href="#company-progression" aria-label="Permalink to &quot;Company Progression&quot;">​</a></h2><p>Creating a Company is only the beginning of the Company progression system.</p><p>After creating a Company, members can work together to:</p><ul><li>Complete Company Orders</li><li>Gather required Materials</li><li>Complete Shipments</li><li>Earn Company rewards</li><li>Progress through the current Season</li><li>Work towards Company equipment and other rewards</li></ul><h2 id="useful-tips" tabindex="-1">Useful Tips <a class="header-anchor" href="#useful-tips" aria-label="Permalink to &quot;Useful Tips&quot;">​</a></h2><ul><li>Make sure you have enough Coins before attempting to create a Company.</li><li>Consider creating a Company with players you regularly play with.</li><li>Assign appropriate permissions to trusted members.</li><li>Keep track of the current Company Season, as requirements and rewards may change.</li><li>Coordinate Company members when completing larger Orders.</li><li>New members can contribute towards Company progression after joining.</li></ul><blockquote><p><strong>Note:</strong> Company features are subject to change as new Seasons and updates are released.</p></blockquote>',31)])])}const d=a(t,[["render",i]]);export{y as __pageData,d as default};
